#!/usr/bin/env python3
"""Сколько терминов, добавленных в глоссарий 10.10.2026, встречается в каждой главе EPUB (для выбора главы на проверку).
  python chapter_terms.py book.epub
"""
import re, sys, zipfile
from html import unescape
TERMS = ["servlet", "servlet container", "initializer", "accessor", "accessor method", "mutator method", "getter method", "setter method", "formatter", "logger", "log level", "appender", "mapper", "validator", "resolver", "executor", "executor service", "scheduler", "delimiter", "substring", "semicolon", "whitespace", "underscore", "backslash", "forward slash", "square bracket", "curly brace", "angle bracket", "left parenthesis", "right parenthesis", "double quote", "exclamation mark", "ampersand", "newline", "newline character", "carriage return", "line terminator", "escape sequence", "blank space", "operand", "unary operator", "arithmetic operator", "assignment operator", "decrement operator", "increment operator", "bitwise operator", "operator precedence", "hexadecimal", "predicate", "tuple", "modifier", "lifecycle", "rollback", "keystore", "filesystem", "hostname", "filename", "pathname", "locale", "daemon", "descriptor", "deployment descriptor", "enumeration", "enumerated type", "enum type", "supertype", "subinterface", "superinterface", "subpackage", "subclassing", "immutability", "atomicity", "nullability", "internationalization", "pseudocode", "traversal", "subtree", "format specifier", "meta-annotation", "annotation-based", "antipattern", "checkbox", "radio button", "dialog box", "autoconfiguration", "auto-configuration", "in-memory", "in-memory database", "comma-separated list", "comma-separated", "two-dimensional array", "multidimensional array", "one-dimensional array", "three-dimensional array", "jagged array", "method invocation", "method call", "no-argument constructor", "canonical constructor", "parameterized type", "raw type", "generic type", "compile-time error", "compilation error", "run-time error", "uncaught exception", "string concatenation", "markup language", "abstract method", "overloaded method", "overridden method", "helper method", "convenience method", "utility class", "entity class", "controller class", "enclosing class", "top-level class", "class hierarchy", "inheritance hierarchy", "business logic", "boilerplate code", "resource bundle", "for-each loop", "do-while loop", "if-else statement", "try-catch statement", "try-with-resources statement", "single-line comment", "initial value", "right-hand side", "left-hand side", "narrowing conversion", "widening conversion", "type conversion", "formal parameter", "argument list", "recursive call", "random number", "pseudorandom number", "unicode character", "data type", "java compiler", "java virtual machine", "java bytecode", "java platform", "java development kit", "source file", "jar file", "executable jar", "war file", "zip file", "command-line tool", "development environment", "scripting language", "fluent api", "singly linked list", "ascending order", "descending order", "downstream collector", "structured concurrency", "carrier thread", "scoped value", "thread dump", "heap dump", "memory-mapped file", "unnamed module", "native image", "user-defined type", "single-element annotation", "crud operation", "data access", "data integrity", "data source", "jdbc driver", "nosql database", "entity manager", "many-to-one relationship", "many-to-many relationship", "one-to-many relationship", "one-to-one relationship", "presentation layer", "externalized configuration", "spring bean", "bean", "bean method", "bean definition", "starter dependency", "transitive dependency", "parent pom", "cross-cutting concern", "join point", "exploratory testing", "unit-testing framework", "user story", "name-value pair", "package-private", "read-only", "short-circuit evaluation", "happens-before relationship", "just-in-time compiler", "mark-and-sweep", "work-stealing", "thread-per-request", "divide-and-conquer", "fail-fast", "single-page application", "web browser", "integration flow", "service activator", "channel adapter", "message converter", "health indicator", "container image", "docker image", "postfix operator", "prefix operator", "property injection", "constructor injection", "setter injection", "field injection", "autowiring", "component scanning", "application context", "persistence layer", "data persistence", "serverless", "kubernetes cluster", "pod", "inter-service communication", "service-oriented architecture", "consumer-driven contract", "cloud-native application", "containerized application", "twelve-factor app", "reactive manifesto", "reactive stream", "server-sent event", "restful web service", "web service", "stand-alone application", "publish-subscribe", "point-to-point", "round-robin", "peer-to-peer", "client-server", "liveness probe", "readiness probe", "columnstore database", "column-family database", "csrf protection", "cross-origin resource sharing", "authorization server", "authenticated user", "form-based login", "self-signed certificate", "one-time password", "multifactor authentication", "grant type", "symmetric-key algorithm", "elliptic curve", "classpath", "Javadoc", "instanceof", "javac", "println", "UUID", "AOP", "AMQP", "VARCHAR", "NIO", "AWT", "kubectl", "bcrypt", "Actuator", "Buildpacks", "Micrometer", "Minikube", "camelCase", "try-catch", "POM", "remember-me"]
z = zipfile.ZipFile(sys.argv[1])
rows = []
for n in sorted(z.namelist()):
    if not n.endswith((".xhtml", ".html")) or n.endswith("nav.xhtml"): continue
    t = unescape(re.sub(r"<[^>]+>", " ", re.sub(r"<pre.*?</pre>", " ", z.read(n).decode("utf-8", "ignore"), flags=re.S)))
    title = re.search(r"<h1[^>]*>(.*?)</h1>", z.read(n).decode("utf-8", "ignore"), re.S)
    hits = {w: len(re.findall(r"(?<![\w-])%s(?:s|es)?(?![\w-])" % re.escape(w), t, re.I)) for w in TERMS}
    hits = {w: c for w, c in hits.items() if c}
    rows.append((sum(hits.values()), len(hits), n.split("/")[-1], re.sub(r"<[^>]+>|\s+", " ", title.group(1)).strip()[:50] if title else "", len(t.split())))
for total, distinct, name, title, words in sorted(rows, reverse=True)[:12]:
    print(f"{name:14} вхождений {total:4}, разных {distinct:3}, слов {words:6}  {title}")
